"""Summarize latency samples in memory. No network, storage, retries or CLI."""

def summarize_ms(samples: list[float]) -> dict[str, float]:
    """Return count, minimum and maximum milliseconds; reject empty samples."""
    if not samples:
        raise ValueError('samples must not be empty')
    return {'count': len(samples), 'min_ms': min(samples), 'max_ms': max(samples)}
